-- 2026-10-31a: MP Background timelines for 10 more MPs, batch 2 (owner's approval, "yes", 31 Oct 2026).
-- Sets background_timeline (87 entries in all, copied exactly from the batch 2 data file, which is not committed) and
-- background_last_checked = 2026-10-31 for member_ids 5168, 4998, 5099, 163, 4212, 3935, 249, 345, 4769, 4743, each only
-- WHERE background_timeline IS NULL. Every entry passed lib/background-timeline.ts validate() and every source link was
-- checked before this was written. Nothing else changes. Needs no code change: the columns (2026-10-24b) and the MP page
-- Background section are already live on main and work.
-- The 10 rows' previous values are backed up off the repo ("Claude outputs/backups/2026-10-31a-mp-biography-before.csv").
-- Guards (RAISE): exactly 10 rows change, all of them these 10; the 10 pilot timelines (2026-10-24c/d) are unchanged
-- (md5 before and after); the count of non-NULL timelines goes from 10 to 20; each new timeline equals the data file.
-- Undo: 2026-10-31a-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (5168, 4998, 5099, 163, 4212, 3935, 249, 345, 4769, 4743)) <> 10 THEN RAISE EXCEPTION 'expected 10 biography rows for the batch 2 MPs'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (5168, 4998, 5099, 163, 4212, 3935, 249, 345, 4769, 4743) AND background_timeline IS NOT NULL) THEN
    RAISE EXCEPTION 'a batch 2 MP already has a timeline';
  END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 10 THEN RAISE EXCEPTION 'expected 10 timelines before (the pilot)'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309) AND background_timeline IS NOT NULL) <> 10 THEN RAISE EXCEPTION 'expected the 10 pilot timelines before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
