UPDATE public.mp_biography b SET background_timeline = n.tl, background_last_checked = DATE '2026-10-31'
  FROM bt_new n WHERE b.member_id = n.member_id AND b.background_timeline IS NULL;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  pilot_changed integer;
  set_rows integer;
  non_null integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (5168, 4998, 5099, 163, 4212, 3935, 249, 345, 4769, 4743) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO pilot_changed FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309) AND md5(coalesce(b.background_timeline::text, '')) IS DISTINCT FROM o.th;
  SELECT count(*) INTO set_rows FROM public.mp_biography b JOIN bt_new n USING (member_id)
   WHERE b.background_timeline = n.tl AND jsonb_array_length(b.background_timeline) = n.n AND b.background_last_checked = DATE '2026-10-31';
  SELECT count(*) INTO non_null FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT sum(jsonb_array_length(background_timeline)) INTO entry_total FROM public.mp_biography WHERE member_id IN (5168, 4998, 5099, 163, 4212, 3935, 249, 345, 4769, 4743);
  RAISE NOTICE 'rows changed %, outside batch 2 %, pilot timelines changed %, batch 2 rows set as the data file %, non-NULL timelines %, batch 2 entries %',
    changed, changed_outside, pilot_changed, set_rows, non_null, entry_total;
  IF changed <> 10 THEN RAISE EXCEPTION 'expected exactly 10 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside batch 2 changed', changed_outside; END IF;
  IF pilot_changed <> 0 THEN RAISE EXCEPTION '% pilot timelines changed', pilot_changed; END IF;
  IF set_rows <> 10 THEN RAISE EXCEPTION 'expected 10 batch 2 rows holding the data file timelines, got %', set_rows; END IF;
  IF non_null <> 20 THEN RAISE EXCEPTION 'expected 20 non-NULL timelines after, got %', non_null; END IF;
  IF entry_total <> 87 THEN RAISE EXCEPTION 'entry total is % not 87', entry_total; END IF;
END $$;

COMMIT;
